 "content": "from collections import Counter
from itertools import permutations


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    positions = {}
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0:
                positions.setdefault(g[r][c], []).append((r, c))

    frames = []
    for color, cells in positions.items():
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {(r0, c) for c in range(c0, c1 + 1)}
        perimeter |= {(r1, c) for c in range(c0, c1 + 1)}
        perimeter |= {(r, c0) for r in range(r0, r1 + 1)}
        perimeter |= {(r, c1) for r in range(r0, r1 + 1)}
        if not all(g[r][c] == color for r, c in perimeter):
            continue
        # The outline color should not form a filled block in its interior.
        if any(g[r][c] == color for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)):
            continue
        frames.append((color, r0, r1, c0, c1))

    if not frames:
        return g

    frame_colors = {f[0] for f in frames}
    markers = {color: len(cells) for color, cells in positions.items()
               if color not in frame_colors}
    marker_colors = list(markers)

    capacities = []
    for color, r0, r1, c0, c1 in frames:
        cap = sum(1 for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)
                  if (r + c) % 2 == 0)
        capacities.append(cap)

    # Marker-color population encodes the checkerboard population of its frame.
    if len(marker_colors) >= len(frames):
        best = None
        for selected in permutations(marker_colors, len(frames)):
            cost = sum(abs(markers[col] - cap) for col, cap in zip(selected, capacities))
            if best is None or cost < best[0]:
                best = (cost, selected)
        assignments = best[1]
    else:
        assignments = (marker_colors + [marker_colors[-1]] * len(frames))[:len(frames)]

    # The scattered marker pixels are removed; only outlined shapes and their fills remain.
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0 and g[r][c] not in frame_colors:
                g[r][c] = 0

    for frame, fill in zip(frames, assignments):
        _, r0, r1, c0, c1 = frame
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if (r + c) % 2 == 0:
                    g[r][c] = fill
    return g


if __name__ == '__main__':
    pass
